package br.edu.mediconnect.patterns.facade; import br.edu.mediconnect.model.*; import br.edu.mediconnect.repository.*; import br.edu.mediconnect.service.*;
public class MediConnectFacade { private final InMemoryPatientRepository patients=new InMemoryPatientRepository(); private final InMemoryAppointmentRepository appointments=new InMemoryAppointmentRepository(); private final HospitalApplicationService hospital=new HospitalApplicationService(patients,appointments); public void registerPatient(Patient p){patients.save(p);} public boolean schedule(Appointment a){return hospital.schedule(a);} public boolean requestExam(ExamRequest e,double cost){return hospital.requestExam(e,cost);} public HospitalApplicationService getHospitalService(){return hospital;} public InMemoryAppointmentRepository getAppointmentRepository(){return appointments;} }
